const u=t=>String(t).padStart(2,"0");function i(t){if(!t)return"—";const r=new Date(t);return Number.isNaN(r.getTime())||r.getFullYear()<2e3?"—":`${u(r.getHours())}:${u(r.getMinutes())}:${u(r.getSeconds())}`}function o(t){if(!t)return"—";const r=new Date(t);if(Number.isNaN(r.getTime())||r.getFullYear()<2e3)return"—";const n=Math.round((Date.now()-r.getTime())/1e3);return n<5?"刚刚":n<60?`${n} 秒前`:n<3600?`${Math.floor(n/60)} 分钟前`:n<86400?`${Math.floor(n/3600)} 小时前`:`${Math.floor(n/86400)} 天前`}function f(t){if(t==null||t<=0)return"0:00";const r=Math.floor(t/3600),n=Math.floor(t%3600/60),e=Math.floor(t%60);return r>0?`${r}:${u(n)}:${u(e)}`:`${n}:${u(e)}`}function a(t){if(!t||t<=0)return"0 秒";const r=Math.floor(t/3600),n=Math.round(t%3600/60);if(r>0)return n>0?`${r} 小时 ${n} 分`:`${r} 小时`;const e=Math.floor(t%60);return n>0?e>0?`${n} 分 ${e} 秒`:`${n} 分`:`${e} 秒`}function c(t){return t?t<1e3?`${Math.round(t)}ms`:`${(t/1e3).toFixed(1)}s`:"—"}function d(t){return t==null?"—":t.toLocaleString("zh-CN")}function $(t){return t===0?"免费":t<.01?t.toFixed(4):t.toFixed(2)}function l(t){const r=(t??"").trim();if(!r)return"—";const n=/x\s*([0-9]+(?:\.[0-9]+)?)/i.exec(r);return n?`x${Number(n[1]).toFixed(2)}`:r}function s(t){return t<0?"—":t>=1e9?`${(t/1e9).toFixed(2)}B`:t>=1e6?`${(t/1e6).toFixed(2)}M`:t>=1e3?`${(t/1e3).toFixed(1)}K`:String(t)}function h(t){return t?t.includes("6004")?"当日模型用量用尽":t.includes("429")?"上游限流":t.includes("404")?"上游路径偶发缺失":t.includes("余额")?"积分耗尽":t.includes("12153")?"凭证失效":t:"限流冷却"}export{f as a,h as b,i as c,a as d,o as e,$ as f,l as g,c as m,d as n,s as t};
